"""kernels/muse_decode_layer/measure_corridor_v1.py (C33, MEASUREMENT-ONLY, generated by tools/gen_measure_corridor_v1.py).

No GPU: file rules, kernel_fn / prepare are sonnet_v5f verbatim, generator sync, the prefetch-line arithmetic (LIGHT <= 64 KB per CTA), the decision table, the 14 KB render.
Dev GPU (RTX 2060, sm_75: no Hopper PDL, so every variant is the board's code; FP16 stand-ins where tl.dot needs BF16): the five twin kernels with the L2 prefetch (PFL > 0) are bitwise
the original kernels; the whole study end to end on a small shape (variants build, bitwise vs the board, S / D / H / B lines, <= 14 KB); the graph inspection sees stream priorities.
LAST (Capture patches the device capability for the process): the sm_90a compile of every twin with PDL on - the prefetch precedes griddepcontrol.wait in the PTX - and NVRTC for sm_90 of
the small-M twin source.
Run: set -o pipefail; tools/heavy.sh .venv/bin/python -m pytest -q tests/test_measure_corridor_v1.py"""
import importlib.util
import re
import sys
from pathlib import Path

import pytest
import torch

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(ROOT / "tools"))
sys.path.insert(0, str(ROOT / "tests"))

from tools import local_check as lc  # noqa: E402

PROBLEM = "muse_decode_layer"
MEAS = ROOT / "kernels" / PROBLEM / "measure_corridor_v1.py"
V5F = ROOT / "kernels" / PROBLEM / "sonnet_v5f.py"
needs_cuda = pytest.mark.skipif(not torch.cuda.is_available(), reason="needs a CUDA GPU")


def _load(autorun=False):
    spec = importlib.util.spec_from_file_location("_measure_corridor_v1", MEAS)
    m = importlib.util.module_from_spec(spec)
    m._MC_NO_AUTORUN = not autorun
    spec.loader.exec_module(m)
    return m


@pytest.fixture()
def mod():
    return _load()


# ------------------------------------------------------------------------------------------------------------ no GPU
def test_source_rules_sync_and_verbatim():
    src = MEAS.read_text()
    compile(src, "measure_corridor_v1.py", "exec")
    lines = src.splitlines()
    assert lines[0] == "# okc: problem=muse_decode_layer" and "MEASUREMENT-ONLY" in lines[1] and "NEVER submit" in lines[1]
    for banned in ("subprocess", "urllib", "requests", "socket", "os.system", "import os", "environ", ".tolist(", "from reference", "import reference", "__import__", "_getframe"):
        assert banned not in src, banned
    import gen_measure_corridor_v1 as gen
    assert gen.build() == src, "regenerate: .venv/bin/python tools/gen_measure_corridor_v1.py"
    v = V5F.read_text().splitlines()
    start = next(i for i, line in enumerate(lines) if line.startswith("# sonnet_v5f (C32)"))
    assert lines[start:start + len(v) - 1] == v[1:], "sonnet_v5f is not embedded verbatim (kernel_fn / prepare)"
    assert "MEASUREMENT-ONLY" not in V5F.read_text() and "_mc_" not in V5F.read_text()


def test_variants_budget_and_shapes(mod):
    assert mod._MC_BUDGET_S <= 280 and mod._MC_REPS == 5 and mod._MC_SEEDS == (11, 12, 13) and mod._MC_MAX_BYTES <= 14000
    assert [n for n, _ in mod._MC_VARIANTS] == ["PDL_OFF", "WAITFIRST", "TOOLS_LIGHT", "TOOLS_FULL", "PRIO", "TOOLS_LIGHT+PRIO"]
    assert dict(mod._MC_VARIANTS)["PDL_OFF"] == (False, 0, False) and dict(mod._MC_VARIANTS)["WAITFIRST"] == (True, 0, False)
    assert [i for i, _, _ in mod._MC_SHAPES] == [0, 1, 7, 2, 3, 4, 5]
    assert set(mod._MC_TWINS) == set(mod._MC_TWIN_NAMES)


def test_prefetch_lines_light_is_at_most_64kb_per_cta_and_full_is_the_slice(mod):
    # pooler: BN 32, BK 512, split 1, K 8192, bf16: 16 KB... the slice is 32 rows x 16 KB = 512 KB; light = 64 KB = 16 lines per row, full = 128
    pool = dict(BN=32, BK=512, SPLIT=1, HAS_LO=False)
    a = (None, None, None, None, 1, 4096, 8192)
    assert mod._mc_pfl("_gemv_splitk", 1, a, pool) == 16 and mod._mc_pfl("_gemv_splitk", 2, a, pool) == 128
    rt = dict(BN=64, BK=128, SPLIT=16, HAS_LO=True)           # router T >= 2: hi + lo, 512 bf16 = 1 KB = 8 lines per row
    assert mod._mc_pfl("_gemv_splitk", 1, a, rt) == 4 and mod._mc_pfl("_gemv_splitk", 2, a, rt) == 8
    assert mod._mc_pfl("_router_fix_kernel", 1, (), dict(BN=64, SPLIT=64, K=8192)) == 2 and mod._mc_pfl("_router_fix_kernel", 2, (), dict(BN=64, SPLIT=64, K=8192)) == 2   # 256 B per row: the slice is already below LIGHT
    assert mod._mc_pfl("_unpool_kernel", 1, (), dict(BN=16, SPLIT=2, K=4096)) == 32 and mod._mc_pfl("_unpool_kernel", 2, (), dict(BN=16, SPLIT=2, K=4096)) == 32
    assert mod._mc_pfl("_pre_norm_kernel", 1, (), dict(N=4096)) == 64 and mod._mc_pfl("_epilogue_kernel", 2, (), dict(H=4096)) == 64
    for name, kw, a_ in (("_gemv_splitk", pool, a), ("_gemv_splitk", rt, a), ("_router_fix_kernel", dict(BN=64, SPLIT=64, K=8192), ()), ("_unpool_kernel", dict(BN=16, SPLIT=2, K=4096), ())):
        lines = mod._mc_pfl(name, 1, a_, kw)
        nmat = 2 if (kw.get("HAS_LO") or name == "_router_fix_kernel") else 1
        assert kw["BN"] * lines * 128 * nmat <= 65536 * 1.0001 or lines == 1


def _fake(mod, light=5.0, full=5.0, wait=0.2, prio=0.0, with_diff=False):
    results = {}
    for idx, label, case in mod._MC_SHAPES:
        r = {}
        for n, _ in mod._MC_VARIANTS:
            g = dict(PDL_OFF=0.0, WAITFIRST=wait, TOOLS_LIGHT=light, TOOLS_FULL=full, PRIO=prio).get(n, light + prio)
            r[n] = dict(us=[100.0 - g, 101.0 - g, 99.0 - g], chk=["OK", "OK", "DIFF(1e-3)" if (with_diff and n == "PRIO") else "OK"], seeds=list(mod._MC_SEEDS))
        if label in ("d1s", "d1f"):
            chain = [("nvjet_sm90_tst", 12.2, 0.0), ("_attn_kernel", 5.3, -0.4), ("_gemv_splitk", 18.8, 0.4)]
            r["_stamps"] = {n: dict(chain=chain, sumdur=36.3, sumgap=0.0, overlapped=1, n=3) for n in mod._MC_STAMPED}
            r["_info"] = {"PDL_OFF": (16, {0: 16}, 0, 20), "WAITFIRST": (16, {0: 16}, 3, 20), "PRIO": (16, {-1: 12, 0: 4}, 0, 20)}
        results[label] = r
    return results


def test_decision_table(mod):
    line, g = mod._mc_decision(_fake(mod, light=5.0, full=5.0))
    assert line.startswith("D T1 decode") and "build sonnet_v5g with TOOLS_LIGHT" in line and abs(g["TOOLS_LIGHT"] - 5.0) < 1e-9
    line, _ = mod._mc_decision(_fake(mod, light=5.0, full=2.0))
    assert "corridor congestion confirmed" in line and "build sonnet_v5g" not in line
    line, _ = mod._mc_decision(_fake(mod, light=0.5, full=0.4, wait=0.3))
    assert "ALT-1 fusion first" in line
    line, _ = mod._mc_decision(_fake(mod, light=2.0, full=2.0, wait=0.3, prio=1.5))
    assert "add priority to v5g" in line and "ALT-1" not in line
    line, _ = mod._mc_decision({"d1s": {}})
    assert "no reading" in line


def test_render_size_summary_first_and_format(mod):
    text = mod._mc_render(_fake(mod), dict(gpu="NVIDIA_H200", ovh=4.6, secs=200.0, capable=True, twin="ok", dead={"BN": "fail x"}))
    assert len(text.encode()) <= 14000
    lines = text.splitlines()
    first_b = next(i for i, line in enumerate(lines) if line.startswith("B "))
    assert lines[0].startswith("S corridor v1:") and all(line[:2] in ("S ", "D ", "H ") for line in lines[:first_b])
    assert any(line.startswith("D T1 decode") for line in lines[:first_b]) and any(line.startswith("H d1s TOOLS_LIGHT") for line in lines[:first_b])
    assert any(line.startswith("S graph d1s:") and "prio{-1: 12, 0: 4}" in line and "pdl_edges=3/20" in line for line in lines)
    for line in lines[first_b:]:
        assert re.fullmatch(r"B layer \w+ seed=\d+ \| [\w+]+ us=\d+\.\d\d x=\d+\.\d{3} (OK|DIFF\(\S+\))", line), line
    assert any(" DIFF" in line for line in mod._mc_render(_fake(mod, with_diff=True), dict(gpu="x", ovh=0.0, secs=1.0, capable=False, twin="no", dead={})).splitlines() if line.startswith("S #"))
    big = _fake(mod)
    for r in big.values():
        for st in (r.get("_stamps") or {}).values():
            st["chain"] = st["chain"] * 12
    out = mod._mc_render(big, dict(gpu="x", ovh=0.0, secs=1.0, capable=True, twin="ok", dead={}))
    assert len(out.encode()) <= 14000


# ------------------------------------------------------------------------------------------------------------ dev GPU: the twins
def _drive(mod, dtype):
    """Every host wrapper of the five kernels with synthetic tensors (FP16 stand-ins on sm_75). -> list of output tensors (bitwise comparable)."""
    g = torch.Generator(device="cuda").manual_seed(5)
    r = lambda *s, dt=dtype, sc=1.0: (sc * torch.randn(s, generator=g, device="cuda")).to(dt)
    outs = []
    # pooler (T = 8) and the router at T >= 2 (FP32 hidden, hi + lo) through _gemv_splitk
    x = r(8, 8192)
    outs.append(mod._run(x, r(4096, 8192, sc=0.02), None, 4096, dtype, (32, 512, 1, 4, 4)).clone())
    xr = r(8, 8192, dt=torch.float32)
    outs.append(mod._run(xr, r(256, 8192, sc=0.02), r(256, 8192, sc=1e-4), 256, torch.float32, (64, 128, 16, 4, 4), split_x=True).clone())
    # router T = 1
    st = {"router_hi": r(256, 8192, sc=0.02), "router_lo": r(256, 8192, sc=1e-4), "rfix_part": torch.empty((64, 16, 256), device="cuda"), "rfix_done": torch.zeros(64, dtype=torch.int32, device="cuda")}
    outs.append(mod._router_fix(r(1, 8192, dt=torch.float32), r(1, 8192, dt=torch.float32), st).clone())
    # unpooler (T = 3)
    full = torch.zeros((8192, 4096), dtype=dtype, device="cuda")
    full[:1024] = r(1024, 4096, sc=0.02)
    ust = {"dense": {"unpooler": full}, "unpool_part": torch.empty((8, 16, 1024), device="cuda"), "unpool_done": torch.zeros(64, dtype=torch.int32, device="cuda")}
    outs.append(mod.unpool_sliced(r(3, 4096), ust, (16, 128, 2, 4, 2)).clone())
    # pre-expert norm and epilogue
    outs.append(mod.pre_norm_triton(r(4, 4096), r(4096, sc=0.1)).clone())
    outs.append(mod.epilogue_triton(r(4, 8, 4096), torch.rand((4, 8), generator=g, device="cuda"), torch.randint(-1, 32, (4, 8), generator=g, device="cuda", dtype=torch.int32), r(4096, sc=0.1)).clone())
    torch.cuda.synchronize()
    return outs


@needs_cuda
@pytest.mark.parametrize("pf", [1, 2])
def test_twins_with_prefetch_are_bitwise_the_original_kernels(pf):
    mod = _load()
    base = _drive(mod, torch.float16)
    for n in mod._MC_TWIN_NAMES:
        mod.__dict__[n] = mod._McShim(n)
    mod._MC_CUR.update(pdl=False, pf=pf)                       # sm_75: the prefetch runs (valid PTX on every arch), PDL stays off
    twin = _drive(mod, torch.float16)
    for i, (a, b) in enumerate(zip(base, twin)):
        if i == 1:      # the router at T >= 2 reduces its split-K partials with FP32 atomics: its own run-to-run order noise (the board too), not the twin
            assert float((a - b).norm() / a.norm()) < 1e-6
        else:
            assert torch.equal(a, b), i


@needs_cuda
def test_graph_inspection_sees_stream_priorities(mod):
    x = torch.ones(1 << 20, device="cuda")
    hi, lo = torch.cuda.Stream(priority=-1), torch.cuda.Stream(priority=0)
    for main, expect_hi in ((lo, False), (hi, True)):
        g = torch.cuda.CUDAGraph(keep_graph=True)
        with torch.cuda.graph(g, stream=main):
            a = x * 2
            lo.wait_stream(main)
            with torch.cuda.stream(lo):
                b = x + 1
            main.wait_stream(lo)
            c = a + b
        info = mod._mc_graph_info(g)
        assert info is not None and info[0] == 3
        assert (-1 in info[1]) == expect_hi, info


@needs_cuda
def test_study_end_to_end_small(capsys):
    """The whole harness on a stand-in layer (the real dev-card layer is the 1680-kernel torch fallback: minutes and 5 GB): a fork to the side stream, a few kernels, the 3 outputs of kernel_fn."""
    mod = _load()
    side = torch.cuda.Stream()

    def standin(data, state):
        x = data["attn_input"].float()
        main = torch.cuda.current_stream()
        s = state["side_stream"]
        s.wait_stream(main)
        with torch.cuda.stream(s):
            r = (x * 3.0).sum(-1, keepdim=True)
        y = torch.tanh(x) + 1.0
        main.wait_stream(s)
        ids = torch.arange(8, device=x.device, dtype=torch.int32).expand(x.shape[0], 8).contiguous()
        return (y + r).to(torch.bfloat16), y, ids

    mod.kernel_fn = standin
    mod._mc_orig_prepare = lambda w: {"side_stream": side}
    mod._MC_NO_AUTORUN = False
    mod._MC_SHAPES = [(0, "d1s", dict(batch=1, ctx=500, layer="sliding", dist="soft", page=1)), (1, "d1f", dict(batch=1, ctx=500, layer="full", dist="soft", page=1)),
                      (3, "d16f", dict(batch=2, ctx=300, layer="full", dist="soft", page=1, q_len=8))]
    mod._MC_SEEDS = (11, 12)
    state = mod.prepare({})
    out = capsys.readouterr().out
    lines = [line for line in out.splitlines() if line.startswith(("S ", "D ", "H ", "B "))]
    assert len("\n".join(lines).encode()) <= 14000
    assert lines[0].startswith("S corridor v1:") and any(line.startswith("D T1 decode") for line in lines)
    for n, _ in mod._MC_VARIANTS:
        assert any(re.match(rf"B layer d1s seed=11 \| {re.escape(n)} us=\d+\.\d\d x=\S+ OK", line) for line in lines), (n, out)
    assert not any(line.startswith("B ") and "DIFF" in line for line in lines), out
    assert any(line.startswith("H d1s PDL_OFF") for line in lines) and any(line.startswith("H d1f TOOLS_LIGHT") for line in lines)
    gl = [line for line in lines if line.startswith("S graph d1s:")]
    assert gl and "PRIO:k" in gl[0] and "prio{-1:" in gl[0].split("PRIO:")[1], gl          # the stream priority survives graph capture
    assert "S PRIO survives graph capture: YES" in out
    assert "bitwise vs the board: PDL_OFF=OK WAITFIRST=OK TOOLS_LIGHT=OK TOOLS_FULL=OK PRIO=OK TOOLS_LIGHT+PRIO=OK" in out
    assert mod.S3_PDL is False and state["side_stream"] is side


@needs_cuda
def test_budget_guard_drops_instead_of_running_late(capsys):
    mod = _load()
    mod.kernel_fn = lambda data, state: (data["attn_input"].to(torch.bfloat16), data["attn_input"].float(), torch.zeros((data["attn_input"].shape[0], 8), dtype=torch.int32, device="cuda"))
    mod._mc_orig_prepare = lambda w: {"side_stream": torch.cuda.Stream()}
    mod._MC_SHAPES = [(0, "d1s", dict(batch=1, ctx=500, layer="sliding", dist="soft", page=1))]
    mod._MC_NO_AUTORUN = False
    mod._MC_BUDGET_S = 8.0                                   # nothing fits after the setup: every shape is skipped, the report still prints
    import time as _t
    t = _t.perf_counter()
    mod.prepare({})
    assert _t.perf_counter() - t < 25
    out = capsys.readouterr().out
    assert out.startswith("MC progress") or "S corridor v1:" in out
    assert "skipped (budget)" in out or "B layer d1s" not in out


# ------------------------------------------------------------------------------------------------------------ sm_90 (LAST)
@needs_cuda
def test_sm90_twins_prefetch_before_griddepcontrol_wait_and_small_m_source_compiles():
    from tools import ptx_audit as pa
    mod = _load()
    out = {}
    for pf in (1, 2):
        mod._MC_CUR.update(pdl=True, pf=pf)
        with pa.Capture() as cap:
            for n in mod._MC_TWIN_NAMES:
                mod.__dict__[n] = mod._McShim(n)
            cap.case = f"pf{pf}"
            _drive(mod, torch.bfloat16)
        for r in cap.records:
            if r["name"].startswith("_mc_"):
                c = pa.compile_record(r)
                out[(r["name"], pf)] = c
    names = {k[0] for k in out}
    assert {"_mc_gemv_splitk", "_mc_router_fix_kernel", "_mc_unpool_kernel", "_mc_pre_norm_kernel", "_mc_epilogue_kernel"} <= names, names
    ptx_of = {}
    for pf in (1, 2):
        mod._MC_CUR.update(pdl=True, pf=pf)
        with pa.Capture() as cap:
            for n in mod._MC_TWIN_NAMES:
                mod.__dict__[n] = mod._McShim(n)
            _drive(mod, torch.bfloat16)
        import triton
        from triton.backends.compiler import GPUTarget
        from triton.compiler import ASTSource
        for r in cap.records:
            if not r["name"].startswith("_mc_"):
                continue
            ptx = triton.compile(ASTSource(r["jf"], r["signature"], r["constexprs"], r["attrs"]), target=GPUTarget("cuda", 90, 32), options=r["options"]).asm["ptx"]
            body = re.sub(r"//[^\n]*", "", ptx)
            ip, iw = body.find("prefetch.global.L2"), body.find("griddepcontrol.wait")
            assert ip >= 0 and iw >= 0 and ip < iw, (r["name"], pf, ip, iw)
            assert body.count("prefetch.global.L2") >= 1 and "griddepcontrol.launch_dependents" in body or r["name"] == "_mc_epilogue_kernel"
            ptx_of[(r["name"], pf)] = body
    # a variant without prefetch (PFL = 0) has no prefetch instruction at all (the WAITFIRST kernels are the board's, untouched)
    assert all("prefetch.global.L2" in b for b in ptx_of.values())
    # NVRTC (runs ptxas for sm_90): the small-M twin source, GEMM2 prefetch present before its pdl_wait
    import nvrtc_smallm as nv
    if nv.HAVE_NVRTC:
        src = mod._MC_SM_DEVICE_SRC
        nv.sass_check(src, "sm_90", names=nv.KERNEL_NAMES)
        cubin, low = nv.compile_device(src, "compute_90", want="ptx", names=nv.KERNEL_NAMES)
        ptx = (cubin.decode() if isinstance(cubin, bytes) else cubin)
        g2 = ptx[ptx.index(".entry " + low["w4_smallm_kernel<false,4>"]):]
        g2 = g2[:g2.index(".entry ", 10)] if ".entry " in g2[10:] else g2
        assert "prefetch.global.L2" in g2 and g2.index("prefetch.global.L2") < g2.index("griddepcontrol.wait")
        g1 = ptx[ptx.index(".entry " + low["w4_smallm_kernel<true,8>"]):]
        g1 = g1[:g1.index(".entry ", 10)] if ".entry " in g1[10:] else g1
        assert "prefetch.global.L2" not in g1 or g1.index("griddepcontrol.wait") < g1.index("prefetch.global.L2")      # GEMM1's weights depend on the routing: no prefetch before its wait
